<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\RelyingParty\Domain\ValueObject\Accessor\RelyingPartyApiKeyAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the RelyingPartyApiKeyAccessor trait.
 *
 * Covers null default, string/VO assignment via withApiKey,
 * getApiKey/apiKey accessors, and isApiKeyChanged with/without original.
 */
class RelyingPartyApiKeyAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withApiKey creates a new instance with the ApiKey set
     * from a string value, and getApiKey returns the primitive string.
     */
    public function testWithApiKeyFromString(): void
    {
        // Arrange
        $holder = new ImplWithRelyingPartyApiKeyAccessorUnitTest();

        // Act
        $result = $holder->withApiKey('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getApiKey());
    }
    /**
     * Asserts that withapiKey has access to the value object
     * from a string value, and getApiKey returns the primitive string.
     */
    public function testWithApiKeyFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithRelyingPartyApiKeyAccessorUnitTest();

        // Act
        $result = $holder->withApiKey('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->apiKey()->value());
    }
    public function testChangedApiKey(): void
    {
        // Arrange
        $holder = new ImplWithRelyingPartyApiKeyAccessorUnitTest()->withApiKey('one');
        $original = $holder->withApiKey('one');
        $same = $holder->withApiKey('one');
        $modified = $holder->withApiKey('other');

        // Act
        $withSame = $original->isApiKeyChanged($same);
        $withDiferent = $original->isApiKeyChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithRelyingPartyApiKeyAccessorUnitTest
{
    use RelyingPartyApiKeyAccessor;
}
